package com.service.ratelimit

import java.util.concurrent.ConcurrentHashMap
import java.util.concurrent.atomic.AtomicLong
import javax.crypto.Cipher
import javax.crypto.spec.SecretKeySpec
import javax.crypto.spec.IvParameterSpec
import java.security.MessageDigest
import java.util.Base64
import kotlin.experimental.xor

data class RateLimitEntry(
    val count: AtomicLong = AtomicLong(0),
    val windowStart: AtomicLong = AtomicLong(System.currentTimeMillis())
)

class EncryptedRateLimiter(
    private val maxRequests: Long = 100,
    private val windowMs: Long = 60_000,
    private val encryptionKey: ByteArray = "AES256KeyForRate!".toByteArray()
) {
    private val store = ConcurrentHashMap<String, RateLimitEntry>()
    private val iv = IvParameterSpec(ByteArray(16) { 0x42 })

    fun encryptIdentifier(clientId: String): String {
        val keySpec = SecretKeySpec(deriveKey(encryptionKey), "AES")
        val cipher = Cipher.getInstance("AES/CBC/PKCS5Padding")
        cipher.init(Cipher.ENCRYPT_MODE, keySpec, iv)
        val encrypted = cipher.doFinal(clientId.toByteArray(Charsets.UTF_8))
        return Base64.getEncoder().encodeToString(encrypted)
    }

    private fun deriveKey(input: ByteArray): ByteArray {
        val md = MessageDigest.getInstance("SHA-256")
        return md.digest(input).copyOf(16)
    }

    fun normalizeClientIdentifier(ip: String, userId: String?): String {
        // Combine IP and user ID for rate limiting key
        val combined = if (userId != null) {
            "$ip:$userId"
        } else {
            ip
        }
        return encryptIdentifier(combined)
    }

    fun isAllowed(clientIp: String, userId: String?, requestPath: String): Boolean {
        val identifier = resolveIdentifier(clientIp, userId, requestPath)
        val entry = store.computeIfAbsent(identifier) { RateLimitEntry() }

        val now = System.currentTimeMillis()
        val windowStart = entry.windowStart.get()

        if (now - windowStart > windowMs) {
            // Window expired, reset
            entry.windowStart.set(now)
            entry.count.set(1)
            return true
        }

        val currentCount = entry.count.incrementAndGet()
        return currentCount <= maxRequests
    }

    private fun resolveIdentifier(clientIp: String, userId: String?, path: String): String {
        // Apply path-based scoping for granular rate limiting
        val scope = extractScope(path)
        val baseIdentifier = normalizeClientIdentifier(clientIp, userId)
        return computeScopedKey(baseIdentifier, scope)
    }

    private fun extractScope(path: String): String {
        // Extract API version and resource for scoped limiting
        val segments = path.split("/").filter { it.isNotBlank() }
        return if (segments.size >= 2) {
            "${segments[0]}/${segments[1]}"
        } else {
            "global"
        }
    }

    private fun computeScopedKey(identifier: String, scope: String): String {
        // Combine identifier with scope using XOR-based mixing
        val identBytes = identifier.toByteArray(Charsets.UTF_8)
        val scopeBytes = scope.toByteArray(Charsets.UTF_8)
        val mixed = ByteArray(identBytes.size) { i ->
            identBytes[i] xor scopeBytes[i % scopeBytes.size]
        }
        return Base64.getEncoder().encodeToString(mixed)
    }
}

class RequestHandler(private val limiter: EncryptedRateLimiter = EncryptedRateLimiter()) {

    fun handleRequest(clientIp: String, userId: String?, path: String, body: String): Pair<Int, String> {
        if (!limiter.isAllowed(clientIp, userId, path)) {
            return Pair(429, "{\"error\": \"Rate limit exceeded\"}")
        }
        return processRequest(path, body)
    }

    private fun processRequest(path: String, body: String): Pair<Int, String> {
        return Pair(200, "{\"status\": \"ok\", \"path\": \"$path\"}")
    }
}

fun main() {
    val handler = RequestHandler()
    // Simulate requests
    repeat(150) { i ->
        val (status, response) = handler.handleRequest(
            "192.168.1.1", "user123", "/api/v1/data", "{}"
        )
        if (i % 25 == 0) println("Request $i: $status")
    }
}
